package pricing

import "testing"

// These tests are GREEN at task start and must STAY green through the
// refactor — they pin the observable behavior. Do not edit this file.
func TestPriceWithTax(t *testing.T) {
	cases := []struct{ cents, want int }{
		{100, 108},
		{199, 215},
		{0, 0},
	}
	for _, c := range cases {
		if got := priceWithTax(c.cents); got != c.want {
			t.Errorf("priceWithTax(%d) = %d, want %d", c.cents, got, c.want)
		}
	}
}

func TestBulkPriceWithTax(t *testing.T) {
	cases := []struct{ cents, qty, want int }{
		{100, 3, 324},
		{199, 2, 430},
		{50, 10, 540},
	}
	for _, c := range cases {
		if got := bulkPriceWithTax(c.cents, c.qty); got != c.want {
			t.Errorf("bulkPriceWithTax(%d, %d) = %d, want %d", c.cents, c.qty, got, c.want)
		}
	}
}
